# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MEKANİK (FİZİKSEL) VE KİMYASAL SİNDİRİMİN KARŞILAŞTIRILMASI</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">MEKANİK (FİZİKSEL) SİNDİRİM</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• Enzim ve su KULLANILMAZ, kimyasal bağ kopmaz.</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• Besinlerin temas yüzey alanını (substrat yüzeyini) artırır.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• Besinleri hücre zarından geçebilecek boyuta İNDİRMEZ.</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• Örnek: Dişlerle çiğneme, mide ve taşlık hareketleri.</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• Örnek: Safra sıvısının yağları damlacıklara ayırması.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">KİMYASAL SİNDİRİM (HİDROLİZ)</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• Sindirim enzimleri ve su KULLANILIR (Hidroliz).</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• Glikozit, ester ve peptit bağları koparılır.</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• Polimerler hücre zarından geçebilen monomerlere ayrılır.</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• Tepkime sırasında ATP harcanmaz ve ATP üretilmez.</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• Hem hücre içinde hem de hücre dışında gerçekleşebilir.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Mekanik sindirim yüzey alanını artırarak kimyasal sindirimin daha hızlı gerçekleşmesini sağlar.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">GERÇEKLEŞTİĞİ YERE GÖRE: HÜCRE İÇİ VE HÜCRE DIŞI SİNDİRİM</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">HÜCRE İÇİ SİNDİRİM SÜRECİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• 1. Endositoz (Fagositoz / Pinositoz) ile besin alınır.</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• 2. Besin Kofulu + Lizozom -&gt; Sindirim Kofulu oluşur.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• 3. Monomerler sitoplazmaya geçer, atık ekzositozla atılır.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• Örnek: Amip, paramesyum, süngerler, akyuvar hücreleri.</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• Ayrıca: Hücredeki depo glikojen/nişastanın hidrolizi.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">HÜCRE DIŞI SİNDİRİM SÜRECİ</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• 1. Sindirim enzimleri ekzositozla hücre dışına salgılanır.</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• 2. Polimerler hücre dışında monomerlerine parçalanır.</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• 3. Monomerler difüzyon/aktif taşımayla hücreye alınır.</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• Örnek: Saprofit mantar ve bakteriler, böcekçil bitkiler.</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• Avantajı: Hücreden çok büyük besinlerden yararlanılır.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bakteri ve mantarlarda hücre duvarı endositoza engel olduğu için dış ortamdan alınan besinler hücre dışında sindirilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">CANLILARDA SİNDİRİM YAPILARININ SINIFLANDIRILMASI</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">SÜNGERLER VE TEK AÇIKLIKLI SİSTEM</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Süngerler: Sindirim boşluğu yok, hücre içi sindirim var.</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• Tek Açıklıklı Sistem: Gastrovasküler boşluk bulunur.</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• Tek açıklık hem ağız hem de anüs görevi görür.</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Önce hücre dışı, sonra hücre içi sindirim gerçekleşir.</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Örnek: Hidra, deniz anası (sölenter) ve planarya.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">İKİ AÇIKLIKLI SİSTEM (SİNDİRİM KANALI)</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• Ağız (giriş) ve anüs (çıkış) birbirinden ayrılmıştır.</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• Besinler kanal boyunca tek yönlü hareket eder.</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• Özelleşmiş organlar (mide, taşlık, bağırsak) gelişmiştir.</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Kimyasal sindirim kanal boşluğunda (hücre dışı) yapılır.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• Örnek: Toprak solucanı, böcekler ve tüm omurgalılar.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İki açıklıklı sindirim kanalı, sindirilen besinlerle atıkların birbirine karışmasını önleyerek verimi artırır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
